{{ fiscal_distribution_csv('132241', 'settlement_expenditure') }}
select p.* exclude(phase_id,value,source_amount ,source_amount_unit),p.value as amount,l.cofog_code,l.cofog_status,l.cofog_basis,l.consolidation,l.counterpart_fund from {{ ref('pkg_132241__expenditure') }} p join {{ ref('api_fiscal_settlement_expenditure_lines') }} l using(fiscal_line_id,dataset_id) join {{ ref('int_fiscal_datasets') }} d using(dataset_id) where d.document_kind='settlement' and p.phase_id='executed'
